import com.truckload.controller.*;
public class FeatureProtocolTest {
 static int n=0;static void check(boolean b){n++;if(!b)throw new AssertionError("Feature check "+n);}
 public static void main(String[] args){Telemetry m=new Telemetry();check(!m.extended&&!m.bench);m.apply("CAPS|2|DRIVING,BENCH,MAP");check(m.extended);m.apply("DRIVE_CONFIG|ON|CHASE|100|12ABEF");check(m.driveControl.equals("ON")&&m.drivePattern.equals("CHASE")&&m.driveBrightness==100&&m.colors.get("DRIVE2").equals("12ABEF"));m.apply("BENCH_STATE|1|DRIVE|75|30|1");check(m.bench&&m.benchSensor&&m.benchPercent==75&&m.benchPsi==30);m.apply("BENCH_RESULT|30|15000|80");check(m.benchWeight==15000&&m.benchEstimate==80);check(!m.hasWeight());m.apply("SENSOR|ON|NO_SIGNAL|0.100|0.145");check(m.adcVolts==.1&&m.sensorVolts==.145&&!m.ready());m.apply("GPS|1|41.8781|-87.6298|0|0|12|100|AT_PLANT|0|1");check(m.gpsFix&&m.latitude==41.8781&&m.longitude==-87.6298);m.apply("GPS_CONFIG|250|1|0|41.879|-87.630");check(m.plant&&m.plantLat==41.879&&m.plantLon==-87.630);m.apply("GPS|1|95|200|0|0|1|0|NO_FIX|0|0");check(!m.gpsFix);m.clearLive();check(!m.bench&&!m.gpsFix&&Double.isNaN(m.latitude)&&Double.isNaN(m.psi));for(int z=3;z<=19;z++)for(double lat:new double[]{-80,-45,0,41.8781,80}){double y=MapProjection.y(lat,z);check(Math.abs(MapProjection.latitude(y,z)-lat)<.000001);check(Math.abs(MapProjection.longitude(MapProjection.x(-87.6298,z),z)+87.6298)<.000001);check(Math.abs(MapProjection.near(MapProjection.world(z)-2,z)+2)<.000001);}System.out.println("PASS: "+n+" feature protocol and map projection checks");}
}
